inline const ACW *GetACW(const void *buf) {
  return ::flatbuffers::GetRoot<ACW>(buf);
}

inline const ACW *GetSizePrefixedACW(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<ACW>(buf);
}

inline const char *ACWIdentifier() {
  return "$ACW";
}

inline bool ACWBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, ACWIdentifier());
}

inline bool SizePrefixedACWBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, ACWIdentifier(), true);
}

template <bool B = false>
inline bool VerifyACWBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<ACW>(ACWIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedACWBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<ACW>(ACWIdentifier());
}

inline void FinishACWBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<ACW> root) {
  fbb.Finish(root, ACWIdentifier());
}

inline void FinishSizePrefixedACWBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<ACW> root) {
  fbb.FinishSizePrefixed(root, ACWIdentifier());
}

inline std::unique_ptr<ACWT> UnPackACW(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<ACWT>(GetACW(buf)->UnPack(res));
}

inline std::unique_ptr<ACWT> UnPackSizePrefixedACW(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<ACWT>(GetSizePrefixedACW(buf)->UnPack(res));
}

